# autogenerated, dissect and build my own later

import asyncio
import shlex

from govee_ble_local import discover, create_device

MAC_ADDRESS = "D4:13:68:C4:45:E3"


HELP = """
Commands
--------
on                         Turn bulb on
off                        Turn bulb off
brightness <0-100>         Set brightness
rgb <r> <g> <b>            Set RGB color (0-255 each)
hex <RRGGBB>               Set color using hex, e.g. hex FF8800
temp <kelvin>              Set white temperature (2700-6500 K)
scenes                     List available scene names
scene <name>               Activate a scene
status                     Refresh and display device state
help                       Show this help
quit                       Disconnect and exit

Examples
--------
brightness 40
rgb 255 0 128
hex 00FFAA
temp 3000
scene Sunset
"""


def parse_int(value, minimum, maximum, label):
    try:
        number = int(value)
    except ValueError:
        raise ValueError(f"{label} must be an integer.")

    if not minimum <= number <= maximum:
        raise ValueError(f"{label} must be between {minimum} and {maximum}.")

    return number


async def execute_command(bulb, line):
    parts = shlex.split(line)

    if not parts:
        return True

    command = parts[0].lower()
    args = parts[1:]

    try:
        if command in ("quit", "exit"):
            return False

        elif command == "help":
            print(HELP)

        elif command == "on":
            await bulb.turn_on()
            print("Bulb turned on.")

        elif command == "off":
            await bulb.turn_off()
            print("Bulb turned off.")

        elif command == "brightness":
            if len(args) != 1:
                raise ValueError("Usage: brightness <0-100>")

            value = parse_int(args[0], 0, 100, "Brightness")
            await bulb.set_brightness(value)
            print(f"Brightness set to {value}%.")

        elif command == "rgb":
            if len(args) != 3:
                raise ValueError("Usage: rgb <r> <g> <b>")

            rgb = tuple(parse_int(v, 0, 255, "RGB channel") for v in args)
            await bulb.set_rgb(rgb)
            print(f"Color set to RGB{rgb}.")

        elif command == "hex":
            if len(args) != 1:
                raise ValueError("Usage: hex <RRGGBB>")

            color = args[0].removeprefix("#")
            if len(color) != 6:
                raise ValueError("Hex color must contain six digits.")

            try:
                rgb = tuple(
                    int(color[i:i + 2], 16)
                    for i in (0, 2, 4)
                )
            except ValueError:
                raise ValueError("Invalid hex color.")

            await bulb.set_rgb(rgb)
            print(f"Color #{color.upper()} applied.")

        elif command == "temp":
            if len(args) != 1:
                raise ValueError("Usage: temp <2700-6500>")

            kelvin = parse_int(args[0], 2700, 6500, "Temperature")
            await bulb.set_color_temp(kelvin)
            print(f"Color temperature set to {kelvin} K.")

        elif command == "scenes":
            names = bulb.scene_names
            if not names:
                print("No scene names available.")
            else:
                print("Available scenes:")
                for name in names:
                    print(f"  {name}")

        elif command == "scene":
            if not args:
                raise ValueError('Usage: scene "Scene Name"')

            name = " ".join(args)
            await bulb.set_scene_by_name(name)
            print(f"Scene applied: {name}")

        elif command == "status":
            state = await bulb.update()
            print("Device state:")
            print(state)

        else:
            print(f"Unknown command: {command!r}. Type 'help'.")

    except (ValueError, IndexError) as exc:
        print(f"Invalid command: {exc}")

    except Exception as exc:
        print(f"Command failed: {type(exc).__name__}: {exc}")

    return True


async def main():
    bulb = None

    try:
        print(f"Searching for bulb {MAC_ADDRESS}...")
        devices = await discover(timeout=10, allow_modelled=True)

        info = next(
            (
                device for device in devices
                if device.ble_device.address.lower()
                == MAC_ADDRESS.lower()
            ),
            None,
        )

        if info is None:
            print("Bulb not found. Check its power, MAC address, and Bluetooth.")
            return

        if not info.supported:
            print(f"Unsupported device model: {info.sku}")
            return

        bulb = create_device(
            info.ble_device,
            info.sku,
            info.advertisement,
            allow_modelled=True,
        )

        print(f"Found {info.sku} ({info.ble_device.address})")
        print("Ready. Type 'help' for commands.")

        while True:
            try:
                line = await asyncio.to_thread(input, "govee> ")
            except EOFError:
                break

            if not await execute_command(bulb, line):
                break

    except KeyboardInterrupt:
        print("\nStopping controller...")

    except Exception as exc:
        print(f"Controller error: {type(exc).__name__}: {exc}")

    finally:
        if bulb is not None:
            await bulb.stop()

        print("Controller stopped.")


if __name__ == "__main__":
    asyncio.run(main())
